package kz.zani.mobile
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import org.json.JSONObject
import org.junit.Test
import org.junit.Assert.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*

@OptIn(ExperimentalCoroutinesApi::class) class MemberReferenceTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun api()=APITeamMemberReadRepository(FixtureTeamMemberReadTransport.fromJSON(fixture("team-member-read")))
    @Test fun exactMembershipSourceNestedIdentityStrictBooleanAndNoBusinessQuery()=runTest {
        val d=JSONObject(fixture("team-member-read"));val cases=d.getJSONArray("source_cases");for(i in 0 until cases.length()){val x=cases.getJSONObject(i);val source=TeamMemberReadSource.decode(x.getString("response_json"),x.getInt("business"),x.getInt("id"));assertEquals(x.getString("name"),x.getBoolean("valid"),source!=null);assertEquals(x.getString("name"),x.getBoolean("eligible"),source?.isActive==true)}
        val inputs=d.getJSONArray("input_cases");for(i in 0 until inputs.length()){val x=inputs.getJSONObject(i);assertEquals(x.getString("raw"),if(x.isNull("parsed"))null else x.getInt("parsed"),MemberReferenceIdentifier.parse(x.getString("raw")))}
        val calls=mutableListOf<ReadRequest>();val repo=APITeamMemberReadRepository(ReadTransport {calls+=it;FixtureTeamMemberReadTransport.fromJSON(fixture("team-member-read")).get(it)});val source=repo.member(101,8101);val inactive=repo.member(101,8102);val account=repo.member(101,8103);assertEquals(listOf(ReadRequest("/api/team/members/8101/"),ReadRequest("/api/team/members/8102/"),ReadRequest("/api/team/members/8103/")),calls);assertEquals(8101,source.id);assertEquals(5002,source.user.id);assertNotEquals(source.id,source.user.id);assertFalse(inactive.isActive);assertTrue(account.isActive);assertEquals(ReadProblem.INVALID_PAYLOAD,(runCatching {repo.member(101,9101)}.exceptionOrNull() as ReadException).problem);assertEquals(ReadProblem.DENIED,(runCatching {repo.member(101,8104)}.exceptionOrNull() as ReadException).problem)
    }
    @Test fun actualModelActiveMembershipOnlyDistinctIdsRawInputAndParentScope()=runTest {
        val a=InboxConversationFilesContext(101,901,1,1);val b=InboxConversationFilesContext(202,951,2,1);val m=MemberReferenceModel(api());m.bind(a);m.show();assertEquals("",m.state.rawInput);assertFalse(m.state.canRead);val input=m.input;m.update("8",input);m.update("81",input);m.update("008101",input);val old=m.control;m.read(old);assertEquals(8101,m.state.source!!.id);assertNull(m.state.choice);m.use(old);assertNull(m.state.choice);m.use(m.control);assertTrue(m.state.choice!!.valid);assertEquals(5002,m.state.choice!!.source.user.id);assertEquals("008101",m.state.choice!!.rawInput);m.update("8102",m.input);m.read(m.control);m.use(m.control);assertNotNull(m.state.source);assertFalse(m.canUse);assertNull(m.state.choice);m.update("8103",m.input);m.read(m.control);m.use(m.control);assertTrue(m.state.choice!!.valid);assertEquals(5004,m.state.choice!!.source.user.id);m.controlsBlocked={true};val frozen=m.control;m.clear(m.control);m.update("8101",m.input);m.read(m.control);assertEquals(frozen,m.control);m.controlsBlocked={false};m.update("8104",m.input);m.read(m.control);assertEquals(ReadProblem.DENIED,m.state.problem);assertNull(m.state.source);assertNull(m.state.choice);m.hide();m.show();assertEquals("8104",m.state.rawInput);m.bind(b);m.show();assertEquals("",m.state.rawInput)
        val files=InboxConversationFilesModel(APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files"))),members=api());files.bind(a);assertTrue(files.open(files.control));val p=files.memberReference!!;p.update("008101",p.input);p.read(p.control);p.use(p.control);files.load(files.control);assertEquals("008101",p.state.rawInput);assertNull(p.state.source);assertNull(p.state.choice);assertTrue(p.state.presented);files.items.firstOrNull()?.let {files.select(it,files.control);assertFalse(p.state.presented);files.back(files.control);assertTrue(p.state.presented);assertEquals("008101",p.state.rawInput)};files.bind(b);assertEquals("",p.state.rawInput);assertFalse(p.state.presented)
    }
    private class Held:TeamMemberReadRepository {val pending=mutableListOf<CompletableDeferred<TeamMemberReadSource>>();override suspend fun member(business:Int,id:Int)=withContext(NonCancellable){CompletableDeferred<TeamMemberReadSource>().also {pending+=it}.await()}}
    @Test fun lateSuccessFailureIgnoredCancellationAndBusinessABA()=runTest {
        val a=InboxConversationFilesContext(101,901,1,1);val b=InboxConversationFilesContext(202,951,2,1);val held=Held();val m=MemberReferenceModel(held);m.bind(a);m.show();m.update("8101",m.input);val first=api().member(101,8101);val second=api().member(101,8102);val old=launch {m.read(m.control)};runCurrent();m.update("8102",m.input);val edited=m.control;held.pending[0].complete(first);old.join();assertEquals(edited,m.control);assertNull(m.state.source);val cancel=launch {m.read(m.control)};runCurrent();cancel.cancel();held.pending[1].complete(second);cancel.join();assertFalse(m.state.loading);assertNull(m.state.source);assertNull(m.state.choice);val fail=launch {m.read(m.control)};runCurrent();m.bind(b);m.show();m.update("9101",m.input);val current=m.control;held.pending[2].completeExceptionally(IllegalStateException("late failure"));fail.join();assertEquals(current,m.control);assertNull(m.state.problem);assertEquals("9101",m.state.rawInput);val aba=launch {m.read(m.control)};runCurrent();m.bind(a);m.show();val back=m.control;held.pending[3].complete(api().member(202,9101));aba.join();assertEquals(back,m.control);assertNull(m.state.source);assertNull(m.state.choice);assertEquals("",m.state.rawInput)
    }
}
